type DSU struct {
    parent []int
    rank   []int
}

func NewDSU(n int) *DSU {
    parent := make([]int, n)
    for i := range parent {
        parent[i] = i
    }
    return &DSU{
        parent: parent,
        rank:   make([]int, n),
    }
}

func (d *DSU) find(node int) int {
    cur := node
    for cur != d.parent[cur] {
        d.parent[cur] = d.parent[d.parent[cur]]
        cur = d.parent[cur]
    }
    return cur
}

func (d *DSU) union(u, v int) bool {
    pu := d.find(u)
    pv := d.find(v)
    if pu == pv {
        return false
    }
    if d.rank[pv] > d.rank[pu] {
        pu, pv = pv, pu
    }
    d.parent[pv] = pu
    d.rank[pu] += d.rank[pv]
    return true
}

func countComponents(n int, edges [][]int) int {
    dsu := NewDSU(n)
    res := n
    for _, edge := range edges {
        u, v := edge[0], edge[1]
        if dsu.union(u, v) {
            res--
        }
    }
    return res
}
